#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/clickhouse-clickhouse-keeper-26.10.6-arm64-oci ] || "$F" docker.io/clickhouse/clickhouse-keeper sha256:503ce3458c21cfedba0f0cb7e80b07ba586242f65cd843437ad43f622f606be2 clickhouse/clickhouse-keeper:26.10.6 images/clickhouse-clickhouse-keeper-26.10.6-arm64-oci
[ "$A" = arm64 ] || [ -f images/clickhouse-clickhouse-keeper-26.10.6-amd64.docker.tar ] || "$F" docker.io/clickhouse/clickhouse-keeper sha256:ca2691948bf647fdcfebd48dc3ed304a0f1e19702afde0840504d7a6ba844d52 clickhouse/clickhouse-keeper:26.10.6 images/clickhouse-clickhouse-keeper-26.10.6-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/clickhouse-clickhouse-server-26.10.6-arm64-oci ] || "$F" docker.io/clickhouse/clickhouse-server sha256:d610448be0bfbb32c1aae9dfb900054f7175a77084d692840f95593d60a35274 clickhouse/clickhouse-server:26.10.6 images/clickhouse-clickhouse-server-26.10.6-arm64-oci
[ "$A" = arm64 ] || [ -f images/clickhouse-clickhouse-server-26.10.6-amd64.docker.tar ] || "$F" docker.io/clickhouse/clickhouse-server sha256:9084cd79bde01fa4a99060d8d9cf71acdc4d3df44fce586230f566890277b2d6 clickhouse/clickhouse-server:26.10.6 images/clickhouse-clickhouse-server-26.10.6-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/clickhouse-clickhouse-keeper-26.10.6-amd64.docker.tar images/clickhouse-clickhouse-server-26.10.6-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/clickhouse-clickhouse-keeper-26.10.6-arm64-oci images/clickhouse-clickhouse-server-26.10.6-arm64-oci
